settings.custom_css:
.botao{
    overflow: hidden !important;
    border-radius: 10px;
}

.botao .elementor-button{
    background: linear-gradient(
        -45deg,
        #E14722,
        #B93216,
        #E14722,
        #F05A32,
        #E14722,
        #B93216
    );
    background-size: 800% 400%;
    transition: all .3s;
    animation: gradient 2.5s infinite cubic-bezier(.62, .28, .23, .99) both;
}

@keyframes gradient {
    0%, 100% {
        background-position: 0% 50%;
    }

    50% {
        background-position: 100% 50%;
    }
}

.botao .elementor-button-text{
    align-self: center;
    padding-right: 0px;
    z-index: 9;
    transition: .3s ease;
}

.botao:hover .elementor-button-text{
    color: #E14722;
    transition: 1.3s ease;
}

.botao .elementor-button::before{
    content: "";
    background: white;
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    border-radius: 10px;
    transform: scaleX(0);
    transform-origin: left;
    transition: .3s ease;
}

.botao:hover .elementor-button::before{
    transform: scaleX(1);
    transform-origin: left;
    transition: 1.3s ease;
}

.botao .elementor-button::after{
    content: '';
    background: linear-gradient(
        10deg,
        rgba(255,255,255,.75) 12.81%,
        rgba(255,255,255,0) 66.66%
    );

    mix-blend-mode: overlay;

    width: 90px;
    height: 160%;

    position: absolute;
    bottom: 0%;

    transform: translateX(-50%) skew(-25deg);

    user-select: none;
    pointer-events: none;

    animation: shinery 2s infinite ease-in-out;
}

@keyframes shinery{

    0% {
        left: -10%;
        opacity: 0;
    }

    10% {
        opacity: 1;
    }

    60% {
        left: 140%;
        opacity: 1;
    }

    65% {
        opacity: 0;
    }

    100% {
        left: 140%;
        opacity: 0;
    }
}

selector .swiper-wrapper {
      -webkit-transition-timing-function: linear !important;
      -moz-transition-timing-function: linear !important;
      -o-transition-timing-function: linear !important;
      transition-timing-function: linear !important; 
}

@media(max-width:432px){
    selector .swiper-slide-image{
        width:350px !important;
    }
}

selector::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(
        to left,
        #050505 0%,
        rgba(5, 5, 5, 0) 10%
    );
    z-index: 2;
}

